import socket
import ipaddress
import requests
from typing import Optional, Dict, Any

def get_geolocation_for_host(host: str, timeout: float = 5.0, token: Optional[str] = None) -> Dict[str, Any]:
    """
    Resolve the given host to an IP address and fetch geolocation info from ipinfo.io.

    Parameters:
    - host: hostname or IP string to resolve (e.g., "example.com" or "8.8.8.8").
    - timeout: timeout in seconds for the HTTP request to ipinfo.io (default 5.0).
               DNS resolution uses the system resolver and may block; this parameter
               does not change DNS resolution timeout.
    - token: optional ipinfo API token; if provided, appended as ?token=TOKEN.

    Returns:
    A dict with:
    - success: bool
    - ip: resolved IP as string (when success is True)
    - geo: dict of geolocation data from ipinfo.io (when success is True)
    - error: human-readable error message (when success is False)
    - http_status: HTTP status code returned by ipinfo.io (if applicable)
    """
    # Basic validation / short-circuit if already an IP address
    try:
        ip_obj = ipaddress.ip_address(host)
        ip_str = str(ip_obj)
    except ValueError:
        # Not a raw IP string, attempt DNS resolution
        try:
            # getaddrinfo may return multiple entries; prefer first usable one
            infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
            if not infos:
                return {"success": False, "error": "No address info returned by resolver."}
            # infos entries are tuples; address is at index 4, which is (addr, port) for AF_INET
            # for AF_INET6 it can be (addr, port, flowinfo, scopeid)
            addr_info = infos[0][4]
            ip_str = addr_info[0]
        except socket.gaierror as e:
            return {"success": False, "error": f"DNS resolution failed for host '{host}': {e}"}
        except Exception as e:
            return {"success": False, "error": f"Unexpected error during DNS resolution: {e}"}

    # Build ipinfo URL
    url = f"https://ipinfo.io/{ip_str}/json"
    if token:
        # append token as query param (ipinfo supports ?token=TOKEN)
        url = f"{url}?token={requests.utils.quote(token)}"

    # Query ipinfo
    try:
        resp = requests.get(url, timeout=timeout)
    except requests.exceptions.Timeout:
        return {"success": False, "error": f"Request to ipinfo.io timed out after {timeout} seconds."}
    except requests.exceptions.ConnectionError as e:
        return {"success": False, "error": f"Network connection error when contacting ipinfo.io: {e}"}
    except requests.exceptions.RequestException as e:
        return {"success": False, "error": f"HTTP request error when contacting ipinfo.io: {e}"}

    # Check HTTP status
    if resp.status_code != 200:
        # Try to extract body text for more context
        body_snippet = None
        try:
            body_snippet = resp.text[:1000]
        except Exception:
            body_snippet = "<unable to read response body>"
        return {
            "success": False,
            "error": f"ipinfo.io returned HTTP {resp.status_code}.",
            "http_status": resp.status_code,
            "response_snippet": body_snippet,
        }

    # Parse JSON
    try:
        geo = resp.json()
    except ValueError:
        return {"success": False, "error": "Failed to decode JSON from ipinfo.io response.", "http_status": resp.status_code}

    # If ipinfo returned an error structure, include it
    if isinstance(geo, dict) and geo.get("error"):
        return {"success": False, "error": f"ipinfo.io returned error: {geo.get('error')}", "http_status": resp.status_code}

    return {"success": True, "ip": ip_str, "geo": geo}
```

Notes:
- DNS resolution uses the system resolver (socket.getaddrinfo) and may block according to system settings; there's no per-call DNS timeout exposed here.
- If you expect heavy usage, consider providing an ipinfo token (token parameter) to increase rate limits.
- The function returns concise, parseable results suitable for programmatic use.

