import socket
import ipaddress
import requests
from typing import Optional, Any, Dict


def resolve_and_fetch_ipinfo(host: str, token: Optional[str] = None, timeout: float = 5.0) -> Dict[str, Any]:
    """
    Resolve the IP address for the given host and fetch geolocation info from ipinfo.io.

    Returns a dictionary with the following structure:
      - status: "success" or "error"
      - ip: the resolved IP address (present on success)
      - data: parsed JSON from ipinfo.io (present on success)
      - error: error message (present on error)
      - http_status: HTTP status code returned by ipinfo.io (present on non-200 responses)

    Parameters:
      - host: hostname or IP (v4 or v6) to resolve
      - token: optional ipinfo API token (if provided, sent in Authorization: Bearer <token>)
      - timeout: seconds to wait for network operations (DNS resolution uses system defaults; requests uses this timeout)

    Examples:
      >>> resolve_and_fetch_ipinfo("example.com")
      {'status': 'success', 'ip': '93.184.216.34', 'data': {...}}

      >>> resolve_and_fetch_ipinfo("invalid-hostname")
      {'status': 'error', 'error': 'DNS resolution failed: ...'}

    Notes:
      - Uses the requests library; ensure it's installed in your environment.
      - The function is defensive and returns error information instead of raising for expected failures.
    """
    if not host or not isinstance(host, str):
        return {"status": "error", "error": "host must be a non-empty string"}

    # Step 1: determine whether host is already an IP address
    ip: Optional[str] = None
    try:
        parsed = ipaddress.ip_address(host)
        ip = str(parsed)
    except ValueError:
        # Not a literal IP; attempt DNS resolution
        try:
            # getaddrinfo may return multiple records. Prefer IPv4 if available.
            infos = socket.getaddrinfo(host, None)
            if not infos:
                return {"status": "error", "error": f"DNS resolution returned no addresses for host '{host}'"}
            # Choose first IPv4, otherwise first available
            chosen = None
            for fam, _, _, _, sockaddr in infos:
                if fam == socket.AF_INET:
                    chosen = sockaddr[0]
                    break
            if chosen is None:
                # fallback to first entry's address (could be IPv6)
                chosen = infos[0][4][0]
            ip = chosen
        except socket.gaierror as e:
            return {"status": "error", "error": f"DNS resolution failed: {e}"}
        except Exception as e:
            return {"status": "error", "error": f"Unexpected error during DNS resolution: {e}"}

    # Step 2: query ipinfo.io
    url = f"https://ipinfo.io/{ip}/json"
    headers = {}
    if token:
        headers["Authorization"] = f"Bearer {token}"

    try:
        resp = requests.get(url, headers=headers, timeout=timeout)
    except requests.exceptions.RequestException as e:
        return {"status": "error", "error": f"Network error when contacting ipinfo.io: {e}"}

    # Handle HTTP errors
    if resp.status_code != 200:
        # try to extract any JSON error message, otherwise use text
        detail: Optional[str] = None
        try:
            j = resp.json()
            # ipinfo often returns {"error": {...}} or similar
            detail = str(j)
        except ValueError:
            detail = resp.text.strip() or None
        return {
            "status": "error",
            "error": f"ipinfo.io returned HTTP {resp.status_code}",
            "http_status": resp.status_code,
            "detail": detail,
        }

    # Parse JSON
    try:
        data = resp.json()
    except ValueError:
        # Not valid JSON; return raw text
        return {
            "status": "success",
            "ip": ip,
            "data": {"raw": resp.text},
        }

    return {"status": "success", "ip": ip, "data": data}

