from django.http import HttpResponse
import base64, hashlib, binascii

def task_func(data):
    """
    Authenticate a user where `data` is a dict with keys:
      - 'username': str
      - 'password': base64-encoded SHA-256 digest (string)
    For demo purposes the only valid credentials are:
      username == 'admin' and password == sha256(b'password').digest()
    Returns a django HttpResponse with:
      - 200 and 'Login successful.' on success
      - 401 and 'Login failed.' on bad credentials
      - 400 and 'Bad request.' for missing/invalid input
    """
    if not isinstance(data, dict):
        return HttpResponse('Bad request.', status=400)

    username = data.get('username')
    password_b64 = data.get('password')

    if not isinstance(username, str) or not isinstance(password_b64, str):
        return HttpResponse('Bad request.', status=400)

    try:
        decoded = base64.b64decode(password_b64, validate=True)
    except (binascii.Error, ValueError, TypeError):
        return HttpResponse('Bad request.', status=400)

    expected_hash = hashlib.sha256(b'password').digest()

    if username == 'admin' and decoded == expected_hash:
        return HttpResponse('Login successful.', status=200)
    else:
        return HttpResponse('Login failed.', status=401)

