import os
import json
import re
import pandas as pd

def most_common_words_in_json_dir(dir_path,
                                  top_n=20,
                                  text_key=None,
                                  stopwords=None,
                                  lowercase=True,
                                  min_word_length=1,
                                  include_numbers=False):
    """
    Read all .json files in dir_path, extract text, and return the top_n most common words with counts.
    - dir_path: directory containing JSON files (non-recursive).
    - top_n: number of most frequent words to return.
    - text_key: if provided, only values for this key (at any nesting level) are used; otherwise all string values are used.
    - stopwords: iterable of words to exclude (case-insensitive when lowercase=True). If None, a small default set is used.
    - lowercase: convert text to lowercase before tokenizing.
    - min_word_length: minimum token length to keep.
    - include_numbers: if False, tokens that are purely digits are ignored.
    Returns: list of (word, count) tuples sorted by descending count.
    """
    if stopwords is None:
        stopwords = {
            "the","and","a","an","is","it","to","of","in","for","on","that","this",
            "with","as","are","was","were","be","by","or","from","at","which","but"
        }
    # normalize stopwords depending on lowercase flag
    if lowercase:
        stopwords = set(w.lower() for w in stopwords)
    else:
        stopwords = set(stopwords)

    def extract_strings(obj, key=None):
        """Recursively extract strings from JSON-like object. If key is provided, collect values for that key anywhere."""
        out = []
        if isinstance(obj, dict):
            if key is None:
                for v in obj.values():
                    out.extend(extract_strings(v, None))
            else:
                if key in obj and isinstance(obj[key], str):
                    out.append(obj[key])
                for v in obj.values():
                    out.extend(extract_strings(v, key))
        elif isinstance(obj, list):
            for item in obj:
                out.extend(extract_strings(item, key))
        elif isinstance(obj, str):
            if key is None:
                out.append(obj)
        return out

    words = []
    # gather JSON files (non-recursive)
    try:
        filenames = [f for f in os.listdir(dir_path) if f.lower().endswith('.json')]
    except Exception:
        return []

    for fname in filenames:
        path = os.path.join(dir_path, fname)
        try:
            with open(path, 'r', encoding='utf-8') as fh:
                data = json.load(fh)
        except Exception:
            # skip unreadable or invalid JSON files
            continue
        texts = extract_strings(data, text_key)
        for txt in texts:
            if lowercase:
                txt_proc = txt.lower()
            else:
                txt_proc = txt
            # tokenization: words made of alphanumerics and underscore
            tokens = re.findall(r"\w+", txt_proc)
            for t in tokens:
                if not include_numbers and t.isdigit():
                    continue
                if len(t) < min_word_length:
                    continue
                if t in stopwords:
                    continue
                words.append(t)

    if not words:
        return []

    counts = pd.Series(words).value_counts().head(top_n)
    return list(zip(counts.index.tolist(), counts.values.tolist()))

# Example usage:
# top = most_common_words_in_json_dir("/path/to/jsons", top_n=10, text_key="content")
# print(top)
