    """
    Export specifications of functions in f_list to a CSV at file_path.
    Columns:
      - 'Function Name'
      - 'Number of Arguments'
      - 'Defaults'         : repr(dict(param_name->default_value))
      - 'Annotations'      : repr(dict(param_name_or_return->annotation))
      - 'Is Lambda'        : bool
    """
    import inspect
    import pandas as pd

    rows = []
    for f in f_list:
        # Basic name
        name = getattr(f, "__name__", None)
        if name is None:
            # fallback for callables without __name__
            try:
                name = type(f).__name__
            except Exception:
                name = repr(f)

        is_lambda = (name == "<lambda>")

        defaults_map = {}
        ann_map = {}
        num_args = None

        if not callable(f):
            # not a callable — record minimal info
            rows.append({
                "Function Name": name,
                "Number of Arguments": None,
                "Defaults": repr({}),
                "Annotations": repr({}),
                "Is Lambda": False,
            })
            continue

        try:
            sig = inspect.signature(f)
            params = sig.parameters
            num_args = len(params)

            # Defaults
            for p in params.values():
                if p.default is not inspect._empty:
                    # represent default value as repr to keep it readable in CSV
                    defaults_map[p.name] = repr(p.default)

            # Annotations for params
            for p in params.values():
                if p.annotation is not inspect._empty:
                    # use repr of the annotation (could be types)
                    ann_map[p.name] = repr(p.annotation)

            # Return annotation
            if sig.return_annotation is not inspect._empty:
                ann_map["return"] = repr(sig.return_annotation)

        except (ValueError, TypeError):
            # inspect.signature may fail for some builtins or exotic callables
            # try to get info from __code__ if available
            defaults_map = {}
            ann_map = {}
            try:
                code = f.__code__
                num_args = code.co_argcount + code.co_kwonlyargcount
            except Exception:
                num_args = None

        rows.append({
            "Function Name": name,
            "Number of Arguments": num_args,
            "Defaults": repr(defaults_map),
            "Annotations": repr(ann_map),
            "Is Lambda": bool(is_lambda),
        })

    df = pd.DataFrame(rows, columns=[
        "Function Name", "Number of Arguments", "Defaults", "Annotations", "Is Lambda"
    ])
    df.to_csv(file_path, index=False)

Below is a small self-contained Python function that uses the requests library to fetch a GitHub user object and recursively normalizes all string data (both keys and values) to ASCII using Unicode decomposition. It returns the normalized data as a dict. It accepts an optional GitHub token to avoid low unauthenticated rate limits.

```python
def get_github_user_ascii(username, token=None, timeout=10):
    """
    Retrieve GitHub user info for `username` and normalize all string data to ASCII.
    Returns a dict of the normalized data.
    Raises requests.HTTPError for HTTP errors.
    """
    import requests
    import unicodedata

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()
    data = resp.json()

    def to_ascii(s):
        if not isinstance(s, str):
            return s
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii").strip()

    def normalize(obj):
        if isinstance(obj, str):
            return to_ascii(obj)
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                new_key = to_ascii(k) if isinstance(k, str) else k
                new[new_key] = normalize(v)
            return new
        if isinstance(obj, list):
            return [normalize(i) for i in obj]
        return obj

    return normalize(data)
