def get_github_user_normalized(username, timeout=10):
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Uses the requests library. Raises requests.HTTPError for non-200 responses and
    ValueError for invalid username input.

    Example:
        info = get_github_user_normalized("octocat")
    """
    import requests
    import unicodedata

    if not isinstance(username, str) or not username:
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json", "User-Agent": "github-normalizer/1.0"}

    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()
    data = resp.json()

    def _normalize(obj):
        # Normalize bytes (decode first), then strings; recurse into containers.
        if isinstance(obj, bytes):
            try:
                s = obj.decode("utf-8", errors="ignore")
            except Exception:
                s = str(obj)
            obj = s

        if isinstance(obj, str):
            # NFKD decomposition then drop non-ASCII
            return unicodedata.normalize("NFKD", obj).encode("ascii", "ignore").decode("ascii")
        elif isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                # normalize keys if they are strings
                nk = _normalize(k) if isinstance(k, (str, bytes)) else k
                new[nk] = _normalize(v)
            return new
        elif isinstance(obj, list):
            return [_normalize(i) for i in obj]
        elif isinstance(obj, tuple):
            return tuple(_normalize(i) for i in obj)
        else:
            # numbers, bool, None, etc. left as-is
            return obj

    return _normalize(data)

