import requests
import unicodedata

def get_github_user_ascii(username, token=None, timeout=10):
    """
    Retrieve a GitHub user's public profile via the GitHub API, normalize all string data to ASCII,
    and return the normalized data as a dict.

    Parameters:
    - username (str): GitHub username
    - token (str|None): optional GitHub personal access token to increase rate limits
    - timeout (int|float): request timeout in seconds

    Returns:
    - dict: normalized user data (strings converted to ASCII)

    Raises:
    - requests.HTTPError: if the HTTP request fails (404, 403, etc.)
    - requests.RequestException: for other request-related errors
    """
    def _normalize(obj):
        if isinstance(obj, str):
            return unicodedata.normalize("NFKD", obj).encode("ascii", "ignore").decode("ascii")
        if isinstance(obj, bytes):
            s = obj.decode("utf-8", "ignore")
            return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                # normalize keys if they are strings
                nk = _normalize(k) if isinstance(k, (str, bytes)) else k
                out[nk] = _normalize(v)
            return out
        if isinstance(obj, list):
            return [_normalize(i) for i in obj]
        if isinstance(obj, tuple):
            return tuple(_normalize(i) for i in obj)
        if isinstance(obj, set):
            # sets are converted to lists to preserve content after normalization
            return [_normalize(i) for i in sorted(obj, key=lambda x: str(x))]
        return obj

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()
    data = resp.json()
    return _normalize(data)

