def count_word_lengths_by_start(data, letter, case_sensitive=False):
    """
    Given a dict of lists containing a 'Word' column, filter rows where 'Word'
    begins with the specified letter (or prefix) and return a dict mapping
    word length -> count of words with that length.

    Parameters:
      - data: dict of lists, must include key 'Word'
      - letter: str, the starting letter (or prefix) to filter by
      - case_sensitive: bool, default False (perform case-insensitive match)

    Returns:
      dict: {word_length (int): count (int)}
    """
    import pandas as pd

    if not isinstance(data, dict):
        raise TypeError("data must be a dict of lists")

    df = pd.DataFrame(data)

    if 'Word' not in df.columns:
        raise KeyError("Input dict must contain a 'Word' column")

    words = df['Word'].astype(str)
    prefix = str(letter)
    if case_sensitive:
        mask = words.str.startswith(prefix, na=False)
    else:
        mask = words.str.lower().str.startswith(prefix.lower(), na=False)

    lengths = words[mask].str.len()
    if lengths.empty:
        return {}

    counts = lengths.value_counts().sort_index()
    return {int(k): int(v) for k, v in counts.items()}

