def count_pos_without_last_word(sentence):
    """
    Count POS tags in `sentence` excluding the last word.
    Returns a dict {pos_tag: count}.
    """
    import re
    from collections import Counter
    import nltk

    # Ensure required resources are available
    for res in ('tokenizers/punkt', 'taggers/averaged_perceptron_tagger'):
        try:
            nltk.data.find(res)
        except LookupError:
            nltk.download(res.split('/')[-1], quiet=True)

    tokens = nltk.word_tokenize(sentence)
    if not tokens:
        return {}

    # Find index of the last token that looks like a word (contains alphanumeric)
    last_word_idx = None
    for i in range(len(tokens) - 1, -1, -1):
        if re.search(r'\w', tokens[i]):
            last_word_idx = i
            break

    if last_word_idx is None:
        return {}

    # Keep tokens before the last word
    tokens_before = tokens[:last_word_idx]
    if not tokens_before:
        return {}

    tagged = nltk.pos_tag(tokens_before)
    tags = [tag for (_, tag) in tagged]
    return dict(Counter(tags))

# Example:
# count_pos_without_last_word("This is a simple test.")  -> counts for "This is a simple"
