def mode_nested(L):
    """
    Return the mode (most common element) of all elements in a nested list-like L.
    Uses scipy.stats.mode. Accepts nested lists/tuples/sets; treats strings as scalars.
    Raises ValueError if no elements are present.

    Example:
        mode_nested([[1, 2, [2, 3]], [2]])  -> 2
    """
    from scipy import stats
    import numpy as np

    def _flatten(x):
        # only flatten common sequence containers, treat strings as scalars
        for item in x:
            if isinstance(item, (list, tuple, set)):
                yield from _flatten(item)
            else:
                yield item

    flat_list = list(_flatten(L))
    if not flat_list:
        raise ValueError("Input contains no elements")

    arr = np.array(flat_list, dtype=object)

    # scipy.stats.mode API differs across versions; try axis=None first, fallback otherwise
    try:
        res = stats.mode(arr, axis=None)
    except TypeError:
        res = stats.mode(arr)

    mode_val = res.mode[0]
    # convert numpy scalar to native Python if possible
    try:
        return mode_val.item()
    except Exception:
        return mode_val

def median_nested(L):
    """
    Compute the median of all numeric elements in a nested list/tuple/ndarray `L`.
    Uses numpy for the median calculation. Raises ValueError if no numeric elements
    or elements cannot be converted to float.
    """
    import numpy as np

    flat = []
    stack = [L]
    while stack:
        x = stack.pop()
        # treat list/tuple/ndarray as containers to flatten; avoid treating strings/bytes as containers
        if isinstance(x, (list, tuple, np.ndarray)):
            stack.extend(x)
        else:
            flat.append(x)

    if not flat:
        raise ValueError("no elements to compute median")

    try:
        arr = np.array(flat, dtype=float)
    except Exception as e:
        raise ValueError("elements are not all numeric") from e

    return float(np.median(arr))

