def nested_iqr(L):
    """
    Calculate the interquartile range (IQR) of all numeric elements in a nested list/tuple/ndarray L.
    Uses scipy.stats.iqr internally.

    Returns:
        float: the IQR (Q3 - Q1)

    Raises:
        TypeError: if a non-numeric element is encountered
        ValueError: if no numeric elements are found
    """
    from scipy.stats import iqr
    import numpy as np
    import numbers

    flat = []

    def _flatten(x):
        if isinstance(x, (list, tuple)):
            for y in x:
                _flatten(y)
        elif isinstance(x, np.ndarray):
            for y in x.ravel():
                _flatten(y)
        else:
            if isinstance(x, numbers.Real):
                flat.append(float(x))
            else:
                # try converting (e.g., numeric strings), otherwise raise
                try:
                    flat.append(float(x))
                except Exception:
                    raise TypeError(f"Non-numeric element encountered: {x!r}")

    _flatten(L)

    if not flat:
        raise ValueError("No numeric elements found in input")

    return float(iqr(flat))  # default rng=(25, 75)
