def nested_iqr(L):
    """
    Compute the interquartile range (IQR) of all numeric elements in a nested list L.
    Uses scipy.stats.iqr. Handles arbitrary nesting of lists/tuples/sets/numpy arrays.
    Raises ValueError if no numeric (non-NaN) values are found.
    """
    from scipy.stats import iqr
    import math
    import numbers
    import numpy as np

    flat = []
    def _flatten(x):
        # treat common containers as iterables to recurse into
        if isinstance(x, (list, tuple, set, np.ndarray)):
            for item in x:
                _flatten(item)
        else:
            flat.append(x)

    _flatten(L)

    # keep only numeric, non-NaN values
    nums = []
    for v in flat:
        if isinstance(v, numbers.Number):
            if not (isinstance(v, float) and math.isnan(v)):
                nums.append(float(v))

    if not nums:
        raise ValueError("No numeric (non-NaN) values found in the nested input")

    return float(iqr(nums))

def iqr_nested(L, nan_policy='omit'):
    """
    Compute the interquartile range (IQR) of all numeric elements in a nested list/iterable L.
    Uses scipy.stats.iqr and numpy. Non-numeric items are ignored; nested iterables (list/tuple/set/ndarray)
    are flattened recursively. By default NaNs are omitted (nan_policy='omit').

    Returns a float (IQR) or raises ValueError if no numeric values are found.
    """
    import numpy as np
    from scipy.stats import iqr as scipy_iqr
    from collections.abc import Iterable

    def _flatten(obj):
        # skip strings/bytes as they are iterable but not numeric containers
        if isinstance(obj, (str, bytes)):
            return
        if isinstance(obj, Iterable):
            for item in obj:
                yield from _flatten(item)
        else:
            yield obj

    vals = []
    for x in _flatten(L):
        try:
            # convert numeric-like values to float (numpy scalars included)
            v = float(x)
        except Exception:
            continue
        vals.append(v)

    if not vals:
        raise ValueError("No numeric values found in input nested list.")

    arr = np.asarray(vals, dtype=float)
    return float(scipy_iqr(arr, rng=(25, 75), nan_policy=nan_policy))

