def move_first_three_to_end(l):
    """
    Convert list l to a numpy array and move the first 3 elements to the end.
    Rotation is done modulo the array length (so it works for lists shorter than 3).
    """
    import numpy as np
    arr = np.asarray(l)
    if arr.size == 0:
        return arr
    return np.roll(arr, -3)

def most_common_per_column(csv_path):
    """
    Read a CSV file (with a header) and return a dict mapping each column name
    to the most common value in that column. If multiple values tie for most
    frequent, the alphabetically first value is chosen.
    If the CSV is empty (no header or no data rows) returns an empty dict.

    Uses numpy for lightweight processing.
    """
    import numpy as np
    from io import StringIO

    # Read header and remaining lines
    try:
        with open(csv_path, 'r', encoding='utf-8') as f:
            header_line = f.readline()
            if not header_line:
                return {}
            header = [h.strip() for h in header_line.rstrip('\n').split(',')]
            # If header is all empty, treat as empty CSV
            if all(h == '' for h in header):
                return {}
            data_text = f.read()
    except FileNotFoundError:
        raise
    except Exception:
        return {}

    # If there are no data rows, return empty dict
    if not data_text.strip():
        return {}

    # Load data into numpy array of strings
    try:
        buf = StringIO(data_text)
        arr = np.genfromtxt(buf, delimiter=',', dtype=str, autostrip=True, encoding='utf-8', comments=None)
    except Exception:
        return {}

    # Normalize arr to 2D array of shape (nrows, ncols)
    if arr.size == 0:
        return {}
    if arr.ndim == 1:
        # single row -> ensure shape (1, ncols)
        arr = arr[np.newaxis, :]

    ncols = arr.shape[1]
    nheader = len(header)
    cols_to_process = min(ncols, nheader)

    result = {}
    for j in range(cols_to_process):
        col = arr[:, j].astype(str)  # ensure string dtype
        # np.unique returns sorted unique values (alphabetical), which helps tie-breaking
        uniques, counts = np.unique(col, return_counts=True)
        if uniques.size == 0:
            continue
        max_count = counts.max()
        # pick first unique with max count (alphabetically first due to np.unique sort)
        candidates = uniques[counts == max_count]
        result[header[j]] = candidates[0]

    return result

