from PIL import Image
import pytesseract

def ocr_with_comment_fallback(image_path: str,
                              lang: Optional[str] = None,
                              try_detect_encoding: bool = True
                              ) -> Tuple[str, Optional[str], str]:
    """
    Open image_path, run OCR with pytesseract, return (text, encoding, source).
    - text: extracted Unicode string (empty string if nothing found)
    - encoding: encoding detected/used for comment fallback (None for OCR result)
    - source: 'ocr' or 'comment' or 'none'

    Parameters:
    - image_path: path to an image file
    - lang: optional Tesseract language code (e.g. 'eng')
    - try_detect_encoding: if True, try to use chardet (if installed) to detect
                           encoding of comment bytes; otherwise try common encodings.
    """
    # Helper to decode comment bytes/values
    def _decode_bytes(b: bytes) -> Tuple[str, Optional[str]]:
        # Handle EXIF UserComment header (8 bytes) if present
        if len(b) >= 8:
            head = b[:8]
            if head.startswith(b'ASCII'):
                b = b[8:]
                for enc in ('ascii', 'utf-8', 'latin-1', 'cp1252'):
                    try:
                        return b.decode(enc, errors='strict'), enc
                    except Exception:
                        continue
            elif head.startswith(b'UNICODE'):
                b = b[8:]
                try:
                    return b.decode('utf-16', errors='replace'), 'utf-16'
                except Exception:
                    pass
            elif head.startswith(b'JIS'):
                b = b[8:]
                for enc in ('shift_jis', 'euc_jp', 'iso-2022-jp'):
                    try:
                        return b.decode(enc, errors='replace'), enc
                    except Exception:
                        continue
        # Try chardet if available
        if try_detect_encoding:
            try:
                import chardet
                det = chardet.detect(b)
                enc = det.get('encoding')
                if enc:
                    try:
                        return b.decode(enc, errors='replace'), enc
                    except Exception:
                        pass
            except Exception:
                pass
        # Fallback common encodings
        for enc in ('utf-8', 'utf-8-sig', 'cp1252', 'latin-1'):
            try:
                return b.decode(enc, errors='replace'), enc
            except Exception:
                continue
        # As a last resort, map bytes directly using latin-1
        return b.decode('latin-1', errors='replace'), 'latin-1'

    # Open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise RuntimeError(f"Unable to open image {image_path}: {e}")

    # Try OCR
    try:
        ocr_text = pytesseract.image_to_string(img, lang=lang) if lang else pytesseract.image_to_string(img)
    except Exception as e:
        # If pytesseract itself fails, continue to fallback to comment extraction
        ocr_text = ""
    if ocr_text and ocr_text.strip():
        return ocr_text, None, 'ocr'

    # Fallback to image comment / EXIF UserComment
    comment_candidate = None

    # 1) Pillow info dictionary (PNG tEXt, JPEG comment, etc.)
    info = getattr(img, "info", {}) or {}
    # Common keys to check
    for k in ('comment', 'Comment', 'comments', 'text', 'png_text', 'Description'):
        if k in info and info[k]:
            comment_candidate = info[k]
            break

    # 2) Some PNG tEXt entries are returned as dict under 'text'
    if comment_candidate is None and isinstance(info.get('text'), dict):
        txtdict = info.get('text')
        if txtdict:
            # join values
            vals = [v for v in txtdict.values() if v]
            if vals:
                comment_candidate = " ".join(vals)

    # 3) EXIF UserComment (tag 37510)
    if comment_candidate is None:
        try:
            exif = img.getexif()
            if exif:
                uc = exif.get(37510)
                if uc:
                    comment_candidate = uc
        except Exception:
            pass

    # If nothing found
    if not comment_candidate:
        return "", None, 'none'

    # If comment is bytes, decode; if str, return as-is
    if isinstance(comment_candidate, bytes):
        decoded, enc = _decode_bytes(comment_candidate)
        return decoded, enc, 'comment'
    elif isinstance(comment_candidate, str):
        return comment_candidate, 'utf-8', 'comment'
    elif isinstance(comment_candidate, (list, tuple)):
        # join parts
        parts = []
        enc_used = None
        for item in comment_candidate:
            if isinstance(item, bytes):
                s, e = _decode_bytes(item)
                parts.append(s)
                if not enc_used:
                    enc_used = e
            else:
                parts.append(str(item))
        return " ".join(parts), enc_used, 'comment'
    else:
        # Unknown type, coerce to string
        return str(comment_candidate), None, 'comment'
```

Example quick usage:
- result_text, encoding, source = ocr_with_comment_fallback("photo.jpg", lang="eng")
- source will be 'ocr' if OCR returned text, 'comment' if text came from image metadata, or 'none' if nothing found.

