from PIL import Image
import pytesseract

def ocr_image_with_encoding_fallback(image_path, src_encoding=None, dst_encoding='utf-8', lang=None):
    """
    Open an image, run OCR with pytesseract, and optionally convert the resulting text's encoding.
    If OCR result is empty (or conversion fails), fall back to reading image comments / EXIF user comment.

    Parameters:
    - image_path: path to the image file
    - src_encoding: if provided, treat the OCR string as if it were decoded from bytes using the
                    wrong encoding and re-decode it from this encoding. Typical usage for fixing
                    mojibake is to set src_encoding to something like 'cp1251', 'iso-8859-1', etc.
    - dst_encoding: target encoding for returned string (defaults to 'utf-8'). The function returns
                    a Python str; dst_encoding is applied when you want to ensure a particular byte
                    encoding round-trip (kept for completeness).
    - lang: optional pytesseract language specifier (e.g. 'eng', 'rus')

    Returns:
    - a Unicode string with OCR (or comment) text, or an empty string if nothing found.

    Notes:
    - This function is intentionally lightweight and only depends on Pillow and pytesseract.
    - The encoding fix attempts to reconstruct original raw bytes by encoding the OCR result
      via 'latin1' (which maps codepoints 0..255 to the same byte values), then decoding with
      src_encoding. If that fails, image comments are returned as a fallback.
    """
    def _extract_comments(im):
        parts = []
        info = getattr(im, 'info', {}) or {}
        # Common comment/info fields (PNG tEXt, JPEG comment, etc.)
        for k, v in info.items():
            if isinstance(v, bytes):
                try:
                    parts.append(v.decode('utf-8', errors='ignore'))
                except Exception:
                    parts.append(v.decode('latin1', errors='ignore'))
            else:
                parts.append(str(v))
        # Try EXIF UserComment (tag 37510)
        try:
            exif = im.getexif()
            if exif:
                uc = exif.get(37510)
                if uc:
                    if isinstance(uc, bytes):
                        # Some UserComment fields start with an encoding marker (e.g. 'ASCII\0\0\0')
                        for prefix in (b'ASCII\x00\x00\x00', b'UNICODE\x00', b'JIS\x00\x00\x00'):
                            if uc.startswith(prefix):
                                uc = uc[len(prefix):]
                                break
                        try:
                            parts.append(uc.decode('utf-8', errors='ignore'))
                        except Exception:
                            parts.append(uc.decode('latin1', errors='ignore'))
                    else:
                        parts.append(str(uc))
        except Exception:
            # ignore exif read errors
            pass
        return "\n".join([p for p in parts if p])

    # Open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise IOError(f"Cannot open image '{image_path}': {e}")

    # Run OCR
    try:
        ocr_text = pytesseract.image_to_string(img, lang=lang) if lang else pytesseract.image_to_string(img)
    except Exception as e:
        ocr_text = ""
    ocr_text = (ocr_text or "").strip()

    # If OCR empty -> fallback to comments right away
    if not ocr_text:
        return _extract_comments(img) or ""

    # If no special encoding requested, return OCR result
    if not src_encoding:
        return ocr_text

    # Try to reconstruct original bytes and decode with src_encoding
    try:
        # Map the OCR Unicode string back to raw bytes (latin1 preserves byte values 0-255)
        raw = ocr_text.encode('latin1', errors='replace')
        converted = raw.decode(src_encoding, errors='strict')  # raise on unrecoverable bytes
        # Ensure result is a Python str; optionally round-trip to dst_encoding if requested
        if dst_encoding and dst_encoding.lower() != 'utf-8':
            converted = converted.encode(dst_encoding, errors='replace').decode(dst_encoding, errors='replace')
        return converted
    except Exception:
        # conversion failed -> fallback to image comments, and if those empty return original OCR text
        comments = _extract_comments(img)
        return comments or ocr_text

# Example usage:
# text = ocr_image_with_encoding_fallback("scan.jpg", src_encoding="cp1251", dst_encoding="utf-8", lang="rus")
