Here's a small, self-contained Python function that uses pytesseract to OCR an image, attempts to convert the OCR result into a requested encoding, and—if OCR yields nothing—falls back to reading image comments/metadata. It returns a bytes object (text encoded using the chosen or detected encoding), the name of the encoding used, and a source indicator ('ocr' or 'comment').

Usage: supply an image path and optionally a target_encoding (default 'utf-8') and pytesseract language string (e.g. 'eng' or 'eng+spa').

Code:

```python
from PIL import Image, ExifTags
import pytesseract

def extract_text_from_image(path, target_encoding='utf-8', lang=None):
    """
    Open image at `path`, run OCR with pytesseract, and return text encoded to `target_encoding`.
    If OCR yields empty/whitespace text, fall back to reading image comments/metadata.

    Returns: (text_bytes, encoding_used, source)
      - text_bytes: bytes of the text encoded in encoding_used
      - encoding_used: name of encoding that was used for the bytes
      - source: 'ocr' if text came from OCR, 'comment' if from image comments/metadata

    Example:
      data, enc, src = extract_text_from_image('scan.jpg', target_encoding='utf-8', lang='eng')
    """
    def _try_encodings(s, preferred):
        # Try preferred encoding strictly first, then some fallbacks.
        enc_candidates = [preferred, 'utf-8', 'cp1252', 'latin-1', 'utf-16']
        seen = []
        for e in enc_candidates:
            if e in seen:
                continue
            seen.append(e)
            try:
                b = s.encode(e)
                return b, e
            except Exception:
                continue
        # Last resort: encode with preferred using replacement of unencodable chars
        return s.encode(preferred, errors='replace'), preferred

    # Open image
    img = Image.open(path)

    # Run OCR
    try:
        if lang:
            ocr_text = pytesseract.image_to_string(img, lang=lang)
        else:
            ocr_text = pytesseract.image_to_string(img)
    except Exception:
        ocr_text = ''

    if ocr_text and ocr_text.strip():
        return _try_encodings(ocr_text, target_encoding) + ('ocr',)

    # OCR empty -> attempt to extract comments/metadata
    parts = []
    # 1) PIL image info (PNG text chunks, JPEG comment)
    for k, v in img.info.items():
        if isinstance(v, bytes):
            try:
                parts.append(v.decode('utf-8', errors='ignore'))
            except Exception:
                parts.append(str(v))
        else:
            parts.append(str(v))

    # 2) EXIF tags (ImageDescription, UserComment, XPComment, etc.)
    try:
        exif = img.getexif()
        if exif:
            for tag_id, val in exif.items():
                tag = ExifTags.TAGS.get(tag_id, tag_id)
                if tag in ('ImageDescription', 'UserComment', 'XPComment', 'XPTitle', 'ImageUniqueID'):
                    if isinstance(val, bytes):
                        try:
                            parts.append(val.decode('utf-8', errors='ignore'))
                        except Exception:
                            parts.append(str(val))
                    else:
                        parts.append(str(val))
    except Exception:
        pass

    comment_text = '\n'.join(p for p in parts if p).strip()
    if comment_text:
        return _try_encodings(comment_text, target_encoding) + ('comment',)

    # Nothing found anywhere -> return empty bytes in preferred encoding
    return b'', target_encoding, 'none'
```

Notes:
- You need pytesseract and Pillow installed.
- The function returns bytes (so the encoding is explicit). If you prefer Unicode str, decode the returned bytes with the returned encoding: text = data.decode(enc).
- You can change or extend the fallback encodings list in _try_encodings as needed.

