import os
import json
import re
from datetime import datetime
from urllib.parse import urlparse

import requests

def download_file_from_json(json_str, key, save_dir=None, timeout=10):
    """
    Parse a JSON string, find the first URL associated with `key` (searches recursively),
    download the content at that URL, and save it to a timestamped file named
    '<sanitized_key>_<timestamp>.txt' where timestamp is formatted as '%Y%m%d%H%M%S%f'.
    The file is saved in `save_dir` or the current working directory if None.

    Args:
        json_str (str): JSON document as a string.
        key (str): The key to search for in the JSON. The value must be a URL string.
        save_dir (str, optional): Directory where the file will be saved. Defaults to cwd.
        timeout (int|float, optional): Timeout for the HTTP request in seconds.

    Returns:
        str: Full path to the saved file.

    Raises:
        ValueError: If JSON parsing fails, the key/URL is not found, or download fails.
    """
    def _is_url(s):
        try:
            p = urlparse(s)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    def _find_url(obj, target):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == target:
                    # accept a plain string URL
                    if isinstance(v, str) and _is_url(v):
                        return v
                    # accept list with first URL-looking string
                    if isinstance(v, (list, tuple)):
                        for item in v:
                            if isinstance(item, str) and _is_url(item):
                                return item
                # otherwise recurse
                found = _find_url(v, target)
                if found:
                    return found
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                found = _find_url(item, target)
                if found:
                    return found
        return None

    # parse JSON
    try:
        data = json.loads(json_str)
    except Exception as e:
        raise ValueError(f"Invalid JSON: {e}")

    url = _find_url(data, key)
    if not url:
        raise ValueError(f"No URL found for key '{key}'")

    # ensure save directory exists
    save_dir = save_dir or os.getcwd()
    os.makedirs(save_dir, exist_ok=True)

    # sanitize key for filename
    safe_key = re.sub(r"[^0-9A-Za-z._-]", "_", str(key)) or "file"
    timestamp = datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    filename = f"{safe_key}_{timestamp}.txt"
    filepath = os.path.join(save_dir, filename)

    # download and write file
    try:
        with requests.get(url, stream=True, timeout=timeout) as resp:
            resp.raise_for_status()
            with open(filepath, "wb") as fout:
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:
                        fout.write(chunk)
    except Exception as e:
        # remove partial file if exists
        try:
            if os.path.exists(filepath):
                os.remove(filepath)
        except Exception:
            pass
        raise ValueError(f"Failed to download or save content from {url}: {e}")

    return filepath
